 Here is an example of a C++ program that generates a Fibonacci sequence using a recursive function, taking the first two sequence elements and the number of sequence elements to generate as inputs from the user. I've included error handling for non-numeric inputs and negative numbers.

```cpp
#include <iostream>
#include <string>
#include <stdexcept>

using namespace std;

void fibonacci(int n, int a = 0, int b = 1) {
    if (n <= 0) throw invalid_argument("Invalid input: n must be positive.");
    if (!isdigit(atypeof(a).name()[0]) || !isdigit(atofirst(a).name()[0])) throw invalid_argument("Invalid input: a must be a digit.");
    if (!isdigit(atofirst(b).name()[0]) || !isdigit(atosecond(b).name()[0])) throw invalid_argument("Invalid input: b must be a digit.");

    if (n == 1) {
        cout << a << endl;
        return;
    }

    fibonacci(n - 1, b, a + b);
    cout << b << ", ";
}

int main() {
    try {
        string a, b_str, n_str;
        cout << "Enter the first two numbers in the sequence: "; cin >> a >> b_str;
        int a_val = stoi(a);
        fibonacci(stoi(n_str), a_val, stoi(b_str));

        string num_str;
        cout << "Enter the number of sequence elements to generate: "; cin >> num_str;
        int num = stoi(num_str);

        cout << "Fibonacci sequence with " << num << " elements:" << endl;
        fibonacci(num);

    } catch (const invalid_argument& e) {
        cerr << "Error: " << e.what() << endl;
        return 1;
    }

    return 0;
}
```

