func replaceHomophones(_ text: String) -> String {
    // Initialize an empty dictionary to store corrections
    var corrections = [String: String]()

    // Iterate through each homophone pair and add entries to the dictionary
    for (incorrect, correct) in homophones {
        corrections[incorrect] = correct
