```javascript
function determineProtocol(inputData) {
  let ipVersion = getIPVersion(inputData.sourceIP, inputData.destinationIP); // Determine IP version
  let protocol;

  if (ipVersion === 6 && inputData.port === 80) {
    protocol = "HTTP over IPv6";
  } else if (ipVersion === 6) {
    protocol = "IPv6";
  } else if (inputData.port === 80) {
    protocol = "HTTP";
  } else {
    protocol = "UDP";
  }

  return protocol;

  function getIPVersion(ip1, ip2) {
    const ip1Array = ip1.split(":").map(Number);
    const ip2Array = ip2.split(":").map(Number);

    if (ip1Array[0] >= 0 && ip1Array[1] >= 0) { // IPv4
      return 4;
    } else if (ip1Array[0] >= 0 && ip1Array[1] < 0) { // IPv6 with leading zeroes
      ip1Array[1] += 16;
      return ip1SameAsDestIP(ip1Array, ip2Array) ? 6 : 0; // Check if source and destination IPs are identical in IPv6 case
    } else { // IPv6 without leading zeroes
      return ip1SameAsDestIP(ip1Array.slice(1), ip2Array.slice(1)) ? 6 : 0;
    }

    function ip1SameAsDestIP(ip1, ip2) {
      for (let i = 0; i < ip1.length; i++) {
        if (ip1[i] !== ip2[i]) return false;
      }
      return true;
    }
  }
}
