```javascript
// Import required modules
const NestFactory = require('@nestjs/core');
const AppModule = require('./app.module');
const { JwtAuthGuard } = require('./auth/jwt-auth.guard');
const { Roles } = require('./auth/roles.decorator');
const { GUEST, USER, ADMIN } = require('./auth/roles.enum');

// Create an array of permissions
const permissions = ['create', 'read', 'update', 'delete'];

// Define the JwtAuthGuard with roles decorator
@JwtAuthGuard()
@Roles(USER, ADMIN)
class CustomAuthGuard {}

// Initialize the application
async function bootstrap() {
  const app = await NestFactory.create(AppModule);

  // Register the custom auth guard
  app.useGlobalGuards(new CustomAuthGuard());

  // Set up the global error handler
  app.use((err, req, res, next) => {
    if (res.headersSent) return next(err);
    res.status(500).json({ message: err.message });
  });

  // Start the server
  await app.listen(3000);
}

