First, let's define the custom hook `useTemperatureConverter` which will handle the conversion logic and state management:

```javascript
import { useState } from 'react';

const conversionRates = {
  celsiusToFahrenheit: (celsius) => (celsius * 9 / 5) + 32,
  fahrenheitToCelsius: (fahrenheit) => (fahrenheit - 32) * 5 / 9,
};

export const useTemperatureConverter = (initialValue, unit) => {
  const [temperature, setTemperature] = useState(initialValue);
  const [unitState, setUnitState] = useState(unit);

  const handleConvert = () => {
    const newTemperature =
      unitState === 'celsius'
        ? conversionRates.celsiusToFahrenheit(temperature)
        : conversionRates.fahrenheitToCelsius(temperature);
    setTemperature(newTemperature);
    setUnitState((prev) => (prev === 'celsius' ? 'fahrenheit' : 'celsius'));
  };

  return { temperature, unitState, handleConvert };
};
```

Now we can create a functional component called `TemperatureConverter` that uses our custom hook:

```javascript
import React from 'react';
import { useTemperatureConverter } from './useTemperatureConverter';

const TemperatureConverter = () => {
  const { temperature, unitState, handleConvert } = useTemperatureConverter(20, 'celsius');

  return (
    <div>
      <p>Temperature: {temperature}°{unitState}</p>
      <button onClick={handleConvert}>Convert</button>
    </div>
  );
};

export default TemperatureConverter;
```

This `TemperatureConverter` component initializes the temperature with a value of 20 degrees Celsius and renders the current temperature along with a button to toggle the temperature unit between C

