 To identify if a given sentence in Go contains a double negative, follow these steps:

1. Create a slice of specific negative words:
```go
negativeWords := []string{"isn't", "am not", "aren't", "doesn't", "don't", "haven't", "hasn't", "hadn't", "won't", "wouldn't", "can't", "couldn't", "shall not", "shouldn't", "may not", "might not", "must not"}
```

2. Define a function `containsDoubleNegative(sentence string) bool` to check for double negatives:
```go
func containsDoubleNegative(sentence string) bool {
    words := strings.Split(sentence, " ") // Split the sentence into words
    for i := range words {
        currentWord := words[i]
        nextWordIndex := i + 1
         // Check if the current word is a negative word or 'not' followed by a negative word
        if (strings.Contains(negativeWords, currentWord) || (nextWordIndex < len(words) && (strings.Contains(negativeWords, words[nextWordIndex]) && currentWord == "not"))) {
            // Check if there's another negative word after this one
            for j := i + 1; j < len(words); j++ {
                if !strings.Contains(negativeWords, words[j]) {
                    break
                }
                if j+1 == len(words) {
                    return true // Found a double negative
                }
            }
            i += len(negativeWords) // Skip all following negative words in the sentence
        }
    }
    return false
}
```

3. Call the function with your example sentence:
```go
sentence := "He isn't not worried about the coronavirus situation"
if containsDoubleNegative(sentence) {
    fmt.Println("The sentence contains a double negative.")
} else {
    fmt.Println("The sentence does not contain a double negative.")
}
```

