 I'd be happy to help you write a PowerShell script to recursively check folders for ACL entries that reference SIDs occurring only in the SIDHistory of any user or group in the Active Directory domain. Here's an example of how you might accomplish this using the `Get-ADObject`, `Test-Path`, and `Get-Acl` cmdlets:

```powershell
# Set your domain context
$DomainController = "your_domain_controller"
$Credentials = Get-Credential

# Function to get SID history of a user or group
function Get-SidHistory($Identity) {
    $Searcher = New-Object System.DirectoryServices.DirectorySearcher("LDAP://DC=$DomainController")
    $Searcher.Filter = "(&(objectClass=user)(samAccountName=$Identity)"
    $SearchResult = $Searcher.FindOne()
    $Searcher.Dispose()

    if ($SearchResult) {
        $ADUser = $SearchResult.Properties | Where-Object {$_.Name -eq "msDS-ManagedBy"} | Select-Object -ExpandProperty Value
        $ADGroupMembership = (Get-ADPrincipalGroupMembership $SearchResult.Properties.SamAccountName -ErrorAction SilentlyContinue)

        # Combine managedBy and group memberships into a list of SIDs
        $Sids = @($ADUser, $ADGroupMembership) | ForEach-Object {$_.DistinguishedName.Split('=')[1]}
        return $Sids
    }
}

# Function to check if a SID is in the SIDHistory of any user or group in the domain
function Check-SidInSidHistory($Sid, $BaseDN) {
    $Searcher = New-Object System.DirectoryServices.DirectorySearcher("LDAP://$BaseDN")
    $Filter = "(objectClass=user OR objectClass=group)(objectSid=$Sid)"
    $SearchResult = $Searcher.Search()
    $Searcher.Dispose()

    if ($SearchResult.Count -gt 0) {
        return $true
    } else {
        foreach ($sidHistory in (Get-SidHistory -Identity "administrator")) {
